@Override
protected boolean shouldRenderAsCluster(@NonNull Cluster<T> cluster) {
  NtMapInteraction nt = clusterManagersController.ntInteraction;
  return cluster.getSize() >= ntMinimumGroupSize
      || (nt != null && nt.remainder(cluster));
}

@Override public void onClustersChanged(Set<? extends Cluster<T>> clusters) {
  NtMapInteraction nt = clusterManagersController.ntInteraction;
  if (nt != null && !clusters.isEmpty()) {
    Cluster<T> first = clusters.iterator().next();
    if (!first.getItems().isEmpty()) nt.clustersChanged(first.getItems().iterator().next().clusterManagerId(), clusters);
  }
  super.onClustersChanged(clusters);
}

private android.graphics.Bitmap ntBitmap(Cluster<T> cluster) {
  return clusterManagersController.ntInteraction.countBitmap(
      getClusterText(getBucket(cluster)), getColor(getBucket(cluster)), getClusterTextAppearance(cluster.getSize()));
